def step(time, start, duration):
    """ Implements vensim's STEP function

    In range [-inf, start) returns 0
    In range [start, start + duration) returns 1
    In range [start + duration, +inf] returns 0
    """
    if time < start:
        return 0
    elif time < start + duration:
        return 1
    else:
        return 0


def triangular(time, start, duration, amplitude):
    """ Implements vensim's TRIANGULAR function

    In range [-inf, start) returns 0
    In range [start, start + duration) returns 1
    In range [start + duration, +inf] returns 0
    """
    if time < start:
        return 0
    elif time < start + duration:
        return amplitude * (time - start) / duration
    else:
        return 0


