    self.runnables.remove(runnable)

def run(self):
    """
    Run the main loop.
    """
    for runnable in self.runnables:
        if not runnable.isDaemon():
            runnable.start()
    while True:
        for runnable in self.runnables:
            if runnable.isAlive():
                runnable.join(0.01)
            else:
                self.runnables.remove(runnable)
        if len(self.runnables) == 0:
            break

