        self.handle_disconnect(command)
    elif command.command == 'SUBSCRIBE':
        self.handle_subscribe(command)
    elif command.command == 'UNSUBSCRIBE':
        self.handle_unsubscribe(command)
    elif command.command == 'SEND':
