def get_locale_from_request(request):
    """
    Get locale from request
    Extracts locale from request and normalizes it

    :param request:         request object
    :return:                string, locale
    """
    locale = request.GET.get('locale', None)
    if locale is None:
        locale = request.COOKIES.get('locale', None)
    if locale is None:
        locale = request.META.get('HTTP_ACCEPT_LANGUAGE', None)
    if locale is None:
        locale = 'en'
    return normalize_locale(locale)

def get_locale_from_user(user):
    """
    Get locale from user
    Extracts locale from user and normalizes it

    :param user:            user object
    :return:                string, locale
    """
    locale = user.profile.locale
    if locale is None:
        locale = 'en'
    return normalize_locale(locale)

def get_locale_from_user_or_request(user, request):
    """
    Get locale from user or request
    Extracts locale from user or request and normalizes it

    :param user:            user object
    :param request:         request object
    :return:                string, locale
    """
    if user is None:
        return get_locale_from_request(request)
    return get_locale_from_user(user)

